if (affaire.type === "DBE") {
  const passees = realiseParAffaire.get(`DBE|${affaire.numero.replace(/^0+/, "")}`) ?? 0;
  return `${formatHeures(passees)} passées${affecteAffiche > 0 ? ` · ${formatHeures(affecteAffiche)} prévues` : ""}`;
